 b=w.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':1440,'height':900},device_scale_factor=1);p=c.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.add_init_script('localStorage.setItem("honro-first-act-profile-1",'+json.dumps(json.dumps(f,ensure_ascii=False))+');');p.goto(os.environ.get('HONRO_QA_BASE','http://127.0.0.1:8772')+'/HONRO.html');p.wait_for_function('window.HonroApp && window.HonroCampaignLoader',timeout=90000);p.evaluate('''async()=>{await HonroCampaignLoader.ensureStage(40);HonroApp.launch(40)}''');p.wait_for_function('HonroApp.engine?.b?.honroStage===40 && HonroApp.dialogue',timeout=90000);p.wait_for_timeout(delay);p.evaluate('HonroApp.frame=()=>{}');p.wait_for_timeout(100)
 d=p.evaluate('''async()=>{const a=HonroApp,s=a.scene,e=a.engine;s.storyTween=null;s.storyFrame=null;s.cinematic=null;s.goalFocus=null;s.manual=true;const before={stats:s.renderCacheStats(),warm:s._guideTiles?.tiles?.size||0};let samples=[];for(const scale of [.848,.94]){s.x=280;s.y=1120;s.scale=scale;s.time=2.5;const t=performance.now();s.render(e,0,a.selected,a.power,false,0,false);const ms=performance.now()-t,bytes=s.canvas.getContext('2d').getImageData(0,0,s.canvas.width,s.canvas.height).data,hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');samples.push({scale,ms,hash,stats:s.renderCacheStats()})}return {before,samples,w:s.canvas.width,h:s.canvas.height}}''');d.update(errors=errors,scope='fixed synthetic screen after guide; manual camera for deterministic raster comparison, not normal gameplay');(out/f'stage40-first-camera-hash-{tag}.json').write_text(json.dumps(d,indent=2));print(json.dumps(d),flush=True);c.close();b.close()
